    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([1, 1, 1]), fmt([6, 5, 4, 3, 2, 1]), fmt([100000]), fmt([2, 3, 5, 7, 11, 13]), fmt([60, 36, 48, 72, 24, 12])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(3):
            tests.append(fmt([rng.randint(1, 40) for _ in range(n)]))
    for _ in range(4):
        tests.append(fmt([rng.randint(1, 100000) for _ in range(40)]))
    tests.append(fmt([rng.randint(1, 100000) for _ in range(3000)]))
    p = list(range(1, 100001))
    rng.shuffle(p)
    tests.append(fmt(p))
    tests.append(fmt([rng.randint(1, 100000) for _ in range(100000)]))
    tests.append(fmt([rng.randint(99000, 100000) for _ in range(100000)]))
    tests.append(fmt([rng.choice([83160, 98280, 95760, 1, 99991, 65536, 99999]) for _ in range(100000)]))
    return tests

